mapper.update:
UPDATE fortune_results
SET result_json = #{resultJson}, status = 'DONE', error = NULL
WHERE id = #{id}

UPDATE fortune_results
SET status = 'FAILED', error = #{error}, attempts = attempts + 1, failed_at = now()
WHERE id = #{id}

UPDATE fortune_results
SET status = 'GENERATING', error = NULL, started_at = now()
WHERE id = #{id}

UPDATE fortune_results
SET deleted_at = now()
WHERE id = #{id}
  AND member_id = #{memberId}
  AND deleted_at IS NULL
